  private parseCommand(parent?:Command):Command { const name=this.take("identifier").value;const cmd=getCommandInstance(name,parent);if(cmd.type==="test")throw new ParseError(`${cmd.name} may not appear as a first command`); if(cmd.mustFollow){const previous=parent?parent.children.at(-1):this.result.at(-1);if(!previous||!cmd.mustFollow.includes(previous.name))throw new ParseError(`the ${cmd.name} command must follow an ${cmd.mustFollow.join(" or ")} command`);} if((cmd.name==="if"||cmd.name==="elsif")&&cmd.defs.length){cmd.checkNextArg("test",this.parseTest(cmd));}else {while(this.current()&&!["semicolon","left_cbracket","right_cbracket"].includes(this.current()!.type)){if(!this.parseValue(cmd))break;}}
    if(cmd.nonDeterministic)cmd.reassignArguments();if(!cmd.iscomplete())throw new ParseError(`missing argument for command ${cmd.name}`);if(cmd.acceptChildren&&cmd.type==="control"){this.take("left_cbracket");while(this.current()?.type!=="right_cbracket"){if(!this.current())throw new ParseError("end of script reached while right_cbracket expected");cmd.addchild(this.parseCommand(cmd));}this.pos++;}else this.take("semicolon");cmd.completeCb();return cmd; }
  parse(input:string|Uint8Array):boolean { let text="";this.result=[];this.error=undefined;this.pos=0;this.comments=[];resetExtensions();try{text=typeof input==="string"?input:new TextDecoder("utf-8",{fatal:true}).decode(input);this.tokens=this.lexer.scan(text);while(this.pos<this.tokens.length){while(this.current()?.type==="hash_comment")this.comments.push(this.take().value.trim());const c=this.parseCommand();c.hashComments=this.comments;this.comments=[];this.result.push(c);}return true;}catch(e){this.extensionError(e,text);return false;} }
